arguments.new_str:
using Aspire.Hosting;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalSetup
{
    private static IDistributedApplicationTestingBuilder? _appHost;
    private static DistributedApplication? _app;
    private static ReportingConfiguration? _reportingConfiguration;

    public static IChatClient ChatClient { get; private set; } = default!;
    public static ReportingConfiguration ReportingConfiguration => _reportingConfiguration!;

    [AssemblyInitialize]
    public static async Task Initialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        ChatClient = _app.Services.GetRequiredService<IChatClient>();

        var storage = new DiskBasedReportingStorage(
            Path.Combine(context.TestRunResultsDirectory!, "eval-results"));

        _reportingConfiguration = new ReportingConfiguration(
            storage,
            chatConfiguration: new ChatConfiguration(ChatClient),
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }

        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }
}

