using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    [TestMethod]
    public async Task AnswersGreeting()
    {
        await using var scenario = await EvalSetup.ReportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(AnswersGreeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await EvalSetup.ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertAllScoresAtOrAbove(result, 3);
    }

    [TestMethod]
    public async Task AnswersFactualQuestion()
    {
        await using var scenario = await EvalSetup.ReportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(AnswersFactualQuestion));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await EvalSetup.ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertAllScoresAtOrAbove(result, 3);
    }

    [TestMethod]
    public async Task FollowsSystemPrompt()
    {
        await using var scenario = await EvalSetup.ReportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(FollowsSystemPrompt));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that always responds in exactly one sentence."),
            new(ChatRole.User, "Explain what .NET Aspire is.")
        };

        var response = await EvalSetup.ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertAllScoresAtOrAbove(result, 3);
    }

    private static void AssertAllScoresAtOrAbove(EvaluationResult result, double threshold)
    {
        foreach (var metric in result.Metrics.Values)
        {
            if (metric is NumericMetric numericMetric && numericMetric.Value.HasValue)
            {
                Assert.IsTrue(
                    numericMetric.Value.Value >= threshold,
                    $"Metric '{numericMetric.Name}' scored {numericMetric.Value.Value}, expected >= {threshold}");
            }
        }
    }
}

